@namespace sv_0c7d0d96e4364f70bb4d91466b396685.Components.Chat

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Services.Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<Services.Channel> OnChannelSelected { get; set; }
}

.channel-sidebar {
    width: 100%;
    height: 100%;
    background: #2b2d31;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

.sidebar-header {
    padding: 14px 16px;
    border-bottom: 1px solid #1e1f22;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

@namespace sv_0c7d0d96e4364f70bb4d91466b396685.Components.Chat

<div class="message-list" @ref="scrollContainer" @onscroll="HandleScroll">
    @if (IsLoadingOlder)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }
    @foreach (var msg in Messages)
    {
        <MessageBubble Message="msg"
                       ReplyCount="GetReplyCount(msg.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="async (emoji) => await OnReact.InvokeAsync((msg.Id, emoji))" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingOlder { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadOlder { get; set; }

    private ElementReference scrollContainer;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId, 0);

    private async Task HandleScroll()
    {
        // Handled via JS interop for scroll-to-top detection
        await OnLoadOlder.InvokeAsync();
    }
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    font-size: 0.8rem;
    color: #72767d;
}

@namespace sv_0c7d0d96e4364f70bb4d91466b396685.Components.Chat

<div class="message-area">
    <div class="area-header">
        <h2># @ChannelName</h2>
        <span class="area-description">@ChannelDescription</span>
    </div>

    <MessageList Messages="Messages"
                 ThreadReplyCounts="ThreadReplyCounts"
                 IsLoadingOlder="IsLoadingOlder"
                 OnOpenThread="OnOpenThread"
                 OnReact="OnReact"
                 OnLoadOlder="OnLoadOlder" />

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingOlder { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadOlder { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #313338;
}

.area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #f2f3f5;
}

.area-description {
    font-size: 0.8rem;
    color: #72767d;
}

@namespace sv_0c7d0d96e4364f70bb4d91466b396685.Components.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageBubble Message="reply" ReplyCount="0" />
            }
        </div>

        <MessageInput Placeholder="Reply…"
                      ButtonLabel="Reply"
                      OnSend="OnSendReply" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Services.Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Services.Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
}

.thread-panel {
    width: 100%;
    height: 100%;
    background: #2b2d31;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
}

.thread-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #f2f3f5;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background 0.15s, color 0.15s;
}

.close-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: rgba(0, 0, 0, 0.1);
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #f2f3f5;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.85rem;
    color: #dcddde;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.thread-divider {
    padding: 8px 16px;
    text-align: center;
    flex-shrink: 0;
}

.thread-divider span {
    font-size: 0.75rem;
    color: #72767d;
    background: #2b2d31;
    padding: 0 8px;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

@namespace sv_0c7d0d96e4364f70bb4d91466b396685.Components.Chat

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
